#!/usr/bin/env bash
# Tests of the gateway (Caddy) generated by write_caddyfile (devbox-lib.sh) — REAL caddy on high ports,
# a fake backend (the "panel") that answers /healthz with "ok" and anything else with the
# X-Forwarded-For it got. Usage: bash tests/gateway.test.sh
set -uo pipefail
HERE="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
T="$(mktemp -d)"; export HOME="$T"
# shellcheck source=devbox-lib.sh
. "$HERE/devbox-lib.sh"
pass=0 fail=0
ok() { if [ "$2" = "0" ]; then echo "  PASS $1"; pass=$((pass + 1)); else echo "  FAIL $1 ${3:-}"; fail=$((fail + 1)); fi; }
command -v caddy >/dev/null || { echo "  SKIP caddy not installed"; exit 0; }
PIDS=()
cleanup() { for p in "${PIDS[@]}"; do kill "$p" 2>/dev/null; done; rm -rf "$T"; }
trap cleanup EXIT
export PANEL_PORT=$((20000 + RANDOM % 20000)) GATEWAY_PORT=$((40000 + RANDOM % 10000))
node -e "require('http').createServer((q,r)=>r.end(q.url==='/healthz'?'ok':String(q.headers['x-forwarded-for']||''))).listen($PANEL_PORT,'127.0.0.1')" & BACKEND=$!; PIDS+=("$BACKEND")
wait_up() { for _ in $(seq 40); do curl -s -o /dev/null "http://127.0.0.1:$1/healthz" && return 0; sleep 0.25; done; return 1; }
code() { curl -s -o /dev/null -w '%{http_code}' "$1"; }

echo "== default: does not trust X-Forwarded-For coming from outside"
unset TRUSTED_PROXIES PANEL_DOMAIN PANEL_ENABLED
write_caddyfile "$T/Caddyfile"
caddy validate --adapter caddyfile --config "$T/Caddyfile" >/dev/null 2>&1; ok "Caddyfile is valid" $?
! grep -q trusted_proxies "$T/Caddyfile"; ok "no trusted_proxies by default" $?
caddy run --adapter caddyfile --config "$T/Caddyfile" >/dev/null 2>&1 & PIDS+=($!)
wait_up "$GATEWAY_PORT"
got="$(curl -s -H 'X-Forwarded-For: 6.6.6.6' "http://127.0.0.1:$GATEWAY_PORT/")"
[ "$got" = "127.0.0.1" ]; ok "forged XFF is replaced by the real IP (rate limit cannot be bypassed)" $? "(got: $got)"
[ "$(curl -s "http://127.0.0.1:$GATEWAY_PORT/healthz")" = "ok" ]; ok "/healthz answers ok while the panel is up" $?

echo "== /healthz really asks the panel"
kill "$BACKEND" 2>/dev/null; wait "$BACKEND" 2>/dev/null
c="$(code "http://127.0.0.1:$GATEWAY_PORT/healthz")"
[ "$c" -ge 500 ]; ok "panel down -> /healthz fails (container becomes unhealthy)" $? "(got: $c)"
! curl -fsS "http://127.0.0.1:$GATEWAY_PORT/healthz" >/dev/null 2>&1; ok "the Dockerfile HEALTHCHECK command (curl -f) fails" $?
PANEL_ENABLED=false write_caddyfile "$T/C0"
grep -q 'respond "ok" 200' "$T/C0" && ! grep -A2 'handle /healthz' "$T/C0" | grep -q reverse_proxy
ok "PANEL_ENABLED=false -> Caddy answers /healthz itself (no panel to ask)" $?
node -e "require('http').createServer((q,r)=>r.end(q.url==='/healthz'?'ok':String(q.headers['x-forwarded-for']||''))).listen($PANEL_PORT,'127.0.0.1')" & PIDS+=($!)

echo "== behind a proxy: TRUSTED_PROXIES and PANEL_DOMAIN"
TRUSTED_PROXIES="private_ranges" write_caddyfile "$T/C2"
grep -q 'trusted_proxies static private_ranges' "$T/C2"; ok "TRUSTED_PROXIES becomes trusted_proxies" $?
PANEL_DOMAIN="panel.example.com" write_caddyfile "$T/C3"
caddy validate --adapter caddyfile --config "$T/C3" >/dev/null 2>&1; ok "Caddyfile with a domain is valid" $?
grep -q '^panel.example.com {' "$T/C3" && ! grep -q 'auto_https off' "$T/C3"; ok "PANEL_DOMAIN turns on automatic HTTPS" $?
grep -q "^http://:$GATEWAY_PORT {" "$T/C3"; ok "PANEL_DOMAIN still keeps a :GATEWAY_PORT site for /healthz" $?
GATEWAY_PORT=443 PANEL_DOMAIN="panel.example.com" write_caddyfile "$T/C4"
caddy validate --adapter caddyfile --config "$T/C4" >/dev/null 2>&1 && ! grep -q '^http://:' "$T/C4"
ok "GATEWAY_PORT=443 with a domain: no clashing extra site" $?

# run the domain config for real: move Caddy's own 80/443 to high ports and use its local CA
# (test only — no ACME, no privileged ports)
HP=$((50000 + RANDOM % 5000)); SP=$((55000 + RANDOM % 5000)); G2=$((60000 + RANDOM % 5000))
GATEWAY_PORT="$G2" PANEL_DOMAIN="panel.example.com" write_caddyfile "$T/C5"
sed -i "0,/^{/s//{\n\thttp_port $HP\n\thttps_port $SP\n\tlocal_certs\n\tskip_install_trust/" "$T/C5"
caddy run --adapter caddyfile --config "$T/C5" >/dev/null 2>&1 & PIDS+=($!)
wait_up "$G2"
[ "$(curl -s "http://127.0.0.1:$G2/healthz")" = "ok" ]; ok "domain mode: http://:GATEWAY_PORT/healthz answers (healthcheck works)" $?
[ "$(code "http://127.0.0.1:$G2/")" = 404 ]; ok "domain mode: the panel is NOT served on plain GATEWAY_PORT" $?

echo
echo "$pass PASS, $fail FAIL"
[ "$fail" = "0" ]
